# *Questão 7:* Crie uma variável chamada salário e atribua um valor a ela. Use uma estrutura
# condicional para verificar se o salário é maior que R$ 5.000,00. Se for, imprima "Salário alto",
# caso contrário, imprima "Salário dentro da média".

import os

os.system('cls' if os.name == 'nt' else 'clear')

salario = float(input("Digite o salário: "))

if salario > 5000:
    print("Salário alto")
else:
    print("Salário dentro da média")                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      